export const code = async (inputs) => {
  // Valores de exemplo: o limite real vem da regra do programa
  const LIMITE_RENDA_PER_CAPITA = 759;
  const IDADE_ADULTA = 18;
  const IDADE_IDOSA = 60;
  const PONTOS = { crianca: 2, idoso: 2, pcd: 3, aluguel: 2, semRenda: 3 };

  const { answers = {}, formName, serviceSlug, submittedAt, userId } = inputs.dados ?? {};
  const membros = Array.isArray(answers.membros) ? answers.membros : [];
  const valor = (v) => Number(v) || 0;
  const idade = (iso) => {
    const nascimento = new Date(iso);
    if (!iso || Number.isNaN(nascimento.getTime())) return null;
    const hoje = new Date();
    let anos = hoje.getFullYear() - nascimento.getFullYear();
    const mes = hoje.getMonth() - nascimento.getMonth();
    if (mes < 0 || (mes === 0 && hoje.getDate() < nascimento.getDate())) anos--;
    return anos;
  };

  // O formulário pede a idade; data de nascimento fica como alternativa
  const idadeDe = (m) => (m.idade !== undefined && m.idade !== '' ? Number(m.idade) : idade(m.data_nascimento));
  const idades = membros.map(idadeDe).filter((a) => a !== null && !Number.isNaN(a));
  const criancas = idades.filter((a) => a < IDADE_ADULTA).length;
  const idosos = idades.filter((a) => a >= IDADE_IDOSA).length;
  const pcd = membros.filter((m) => m.pcd === true).length;
  const pagaAluguel = answers.tipo_moradia === 'alugada';

  const pessoas = membros.length + 1;
  const rendaTotal = valor(answers.renda_responsavel) + membros.reduce((t, m) => t + valor(m.renda_mensal), 0);
  const rendaPerCapita = Math.round((rendaTotal / pessoas) * 100) / 100;
  const elegivel = rendaPerCapita <= LIMITE_RENDA_PER_CAPITA;

  const motivos = [];
  let pontuacao = 0;
  if (criancas) { pontuacao += criancas * PONTOS.crianca; motivos.push(criancas + ' criança(s) ou adolescente(s)'); }
  if (idosos) { pontuacao += idosos * PONTOS.idoso; motivos.push(idosos + ' pessoa(s) idosa(s)'); }
  if (pcd) { pontuacao += pcd * PONTOS.pcd; motivos.push(pcd + ' pessoa(s) com deficiência'); }
  if (pagaAluguel) { pontuacao += PONTOS.aluguel; motivos.push('moradia alugada'); }
  if (rendaTotal === 0) { pontuacao += PONTOS.semRenda; motivos.push('família sem renda'); }

  const recebidoEm = submittedAt ?? new Date().toISOString();
  const protocolo = 'MS-' + recebidoEm.slice(0, 10).replace(/-/g, '') + '-' + Math.random().toString(36).slice(2, 8).toUpperCase();

  // O formulário também calcula a renda per capita; o fluxo recalcula porque é a fonte oficial
  const divergenciaNoCalculo = answers.renda_per_capita !== undefined && Math.abs(valor(answers.renda_per_capita) - rendaPerCapita) > 0.01;

  return {
    protocolo,
    formulario: formName,
    servico: serviceSlug,
    recebidoEm,
    usuario: userId ?? 'não informado',
    municipio: answers.municipio ?? 'não informado',
    pessoas,
    rendaTotal,
    rendaPerCapita,
    limiteRendaPerCapita: LIMITE_RENDA_PER_CAPITA,
    situacao: elegivel ? 'Pré-elegível' : 'Acima do limite de renda',
    pontuacao: elegivel ? pontuacao : 0,
    motivos: motivos.length ? motivos.join(', ') : 'nenhum critério de prioridade',
    divergenciaNoCalculo,
  };
};
